// Purpose: ROW-146 (REQ-041) — through the check endpoint, mixed-case words with a capital letter after
// their first letter (LinkedIn, WhatsApp, PowerPoint, iOS, eCommerce, and a generated sample like them)
// are not flagged mid-sentence or at a sentence start, while an ordinary misspelled word beside them and
// an all-capital word over 5 letters missing its accent (GESTION) are.
// Provenance: the row's named examples (A-042); mixed-case words generated fresh per run
// (freshMixedCase: no dictionary word in any casing); all-capital words generated by the dictionary
// oracle (accentPopulation, upper-cased and checked); no expected value comes from the product.
//
// Test argument
// ROW-146 promise: a word mixing upper- and lower-case letters with a capital after its first letter is
//   never flagged, mid-sentence or at a sentence start, while a misspelled ordinary word next to one is
//   flagged, and an all-capital word of more than 5 letters missing its accent is flagged (REQ-041
//   fail-if, every arm; A-042; A-032 for the all-capital rule it leaves in force).
// ROW-146 wrong product: one with a list of known brands (LinkedIn yes, a fresh "baveLotin" no); one
//   that exempts mixed case only mid-sentence (through the proper-noun rule) and flags "WhatsApp" or
//   "iOS" opening a sentence or a line; one that exempts the whole neighbourhood of a brand, so the
//   misspelling beside it passes; or one that treats any word with a capital as a brand, so GESTION
//   passes.
// ROW-146 given: the five named words and ~15 fresh mixed-case words, each mid-sentence and opening
//   the text, a sentence or a line, each with a fresh lower-case non-word right beside it; GESTION and
//   ~4 generated all-capital unaccented words (over 5 letters) mid-sentence; near misses: the fresh
//   mixed-case words' letters title-cased (no inner capital) opening a sentence; when: POST
//   /api/check; then: exactly the non-words, the all-capital words and the near misses are flagged.
// ROW-146 controls: the non-words and GESTION, in a text with no mixed-case word, are flagged — the
//   path to a flag is reached, so the mixed-case words' silence is the exemption.
// ROW-146 technique: the row's named examples plus a fresh generated sample (no product can list it),
//   in every position; decoys of the same letters without the inner capital; exact comparison.
// cases: ROW-146 target=ROW-146-mixed-case-words-not-flagged-anywhere-while-a-misspelling-beside-them-and-gestion-are control=ROW-146-control-non-words-and-gestion-flagged-without-mixed-case-words

import { test } from '@playwright/test';
import { accentPopulation, asActor, freshNonWord, freshRandom, isDictionaryWord, type Rng } from './harness';
import { Offer, expectExact, fillers, freshMixedCase, requireNotDictionary, titleCase } from './names-terms-helpers';

const NAMED = ['LinkedIn', 'WhatsApp', 'PowerPoint', 'iOS', 'eCommerce'];
const OPENINGS = ['. ', '\n', '\n• ', '? '];

/** All-capital unaccented words of more than 5 letters whose accented capitals the dictionary holds. */
function allCapitals(rng: Rng, n: number): string[] {
  return rng
    .shuffle(accentPopulation())
    .map((p) => ({ bad: p.stripped.toUpperCase(), good: p.word.toUpperCase() }))
    .filter((p) => p.bad.length > 5 && !isDictionaryWord(p.bad) && isDictionaryWord(p.good))
    .slice(0, n)
    .map((p) => p.bad);
}

test('ROW-146-mixed-case-words-not-flagged-anywhere-while-a-misspelling-beside-them-and-gestion-are', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  requireNotDictionary(['GESTION'], 'ROW-146 named all-capital misspelling');
  const mixed = [...NAMED, ...Array.from({ length: 15 }, () => freshMixedCase(rng))];
  const first = rng.pick(mixed);
  const o = new Offer().keep(first, `${first} opening the text`).put(' ').flag(freshNonWord(rng), 'non-word beside a mixed-case word').put(' ' + fillers(rng, 2));
  for (const m of rng.shuffle(mixed)) {
    // mid-sentence, a misspelling right before it
    o.put(' ' + fillers(rng, 1) + ' ').flag(freshNonWord(rng), 'non-word beside a mixed-case word').put(' ').keep(m, `${m} mid-sentence`).put(' ' + fillers(rng, 1));
    // opening a sentence or a line, a misspelling right after it
    o.put(rng.pick(OPENINGS)).keep(m, `${m} opening a sentence or line`).put(' ').flag(freshNonWord(rng), 'non-word beside a mixed-case word').put(' ' + fillers(rng, 1));
  }
  // the near misses: the fresh words' letters with no inner capital, opening a sentence
  for (const m of mixed.slice(NAMED.length, NAMED.length + 4)) o.put('. ').flag(titleCase(m.toLowerCase()), 'the same letters without an inner capital, opening a sentence').put(' ' + fillers(rng, 2));
  // the all-capital words REQ-041 leaves to the all-capital rule
  for (const g of rng.shuffle(['GESTION', ...allCapitals(rng, 4)])) o.put(' ' + fillers(rng, 1) + ' ').flag(g, 'all-capital word missing its accent').put(' ' + fillers(rng, 1));
  o.put('.');
  await expectExact(o, `ROW-146: mixed-case words are never flagged, while the misspellings beside them, their letters without the inner capital at a sentence start, and GESTION are (seed ${rng.seed})`);
});

test('ROW-146-control-non-words-and-gestion-flagged-without-mixed-case-words', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = new Offer().put(fillers(rng, 2, { capital: true }) + ' ').flag('GESTION', 'GESTION mid-sentence');
  for (let i = 0; i < 3; i++) o.put(' ' + fillers(rng, 1) + ' ').flag(freshNonWord(rng), 'non-word');
  o.put(' ' + fillers(rng, 2) + '.');
  await expectExact(o, `ROW-146 control: non-words and GESTION are flagged in a text with no mixed-case word (seed ${rng.seed})`);
});
